module hww_bemsa
  implicit none
  integer, parameter :: wp  = kind(1.0D0)
contains
  function hww_emsav(x,c) result(v)
    implicit none
    real(wp),dimension(1:45)::x
    real(wp),dimension(0:4344)::p
    real(wp),dimension(0:4344)::c
    real(wp)::v
    
    call hww_bemsav(x,p)
    v = dot_product(p,c)
    
    return
  end function hww_emsav

  subroutine hww_bemsav(x,p)
    implicit none
    real(wp),dimension(1:45)::x
    real(wp),dimension(0:47327)::m
    real(wp),dimension(0:4344)::p
    ! ::::::::::::::::::::

    
    call hww_evmono(x,m)
    call hww_evpoly(m,p)
    
    return
  end subroutine hww_bemsav

