      endif
      m=flag
      matom=INT((dble(m)-0.00001d0)/3.d0)+1
      xyzind=MOD(m-1,3)+1


       hww_drdx = 0.d0
      if (matom.eq.i.or.matom.eq.j) then
          hww_drdx=(xyz(i,xyzind)-xyz(j,xyzind))/r(i,j)
       ! Chen: pass r(i,j) into this function rather than computing them
